export const blocks: readonly LiturgyBlock[] = [
  {"id": "ru-mol-0001", "section": "service", "who": "rubric", "text": "Оглавление"},
  {"id": "ru-mol-0002", "section": "service", "who": "rubric", "text": "^ Молитва ко Пресвятой Богородице благодарственная"},
  {"id": "ru-mol-0003", "section": "service", "who": "rubric", "text": "Что Ти принесем, или что Ти воздадим, о Премилостивая Госпоже Владычице, заступнице рода христианскаго, за вся Твоя неисчетная благодеяния, яже присно являеши всем призывающим имя Твое и Твоея помощи просящим. Кто бо притекаяй к Тебе посрамлен и неуслышан от Тебе отходит, о премилосердая Мати?"},
  {"id": "ru-mol-0004", "section": "service", "who": "reader", "text": "Перевод: Что Тебе принесем или что воздадим, о Премилостивая Госпожа Владычица, заступница рода христианского, за все Твои неисчислимые благодеяния, которые всегда оказываешь всем призывающим имя Твое и Твоей помощи просящим. Ибо кто из прибегающих к Тебе посрамленным или неуслышанным от Тебя отходит, о премилосердная Матерь!"},
  {"id": "ru-mol-0005", "section": "service", "who": "reader", "text": "Знаем, Пречистая, что за множество грехов и беззаконий наших недостойны даже и имя Твое пресладкое называть, а не только хвалебные песни от оскверненных уст Тебе предлагать, и лучше нам возлюбить молчание. Но чтобы не показаться нам забывчивыми и неблагодарными перед Тобою, осмеливаемся предлагать Тебе это коленопреклоненное прославление: Ты же, премилосердная Матерь, не погнушайся принять его, как от полноты любящих Тебя сердец возносимое."},
  {"id": "ru-mol-0006", "section": "service", "who": "reader", "text": "Сама Ты, Владычица, благодатью Твоей коснись сердец наших, да как воск растаявший, изольются перед Тобой в слезных благодарениях и прославлениях."},
  {"id": "ru-mol-0007", "section": "service", "who": "reader", "text": "Благодарим Тебя, всеми Восхваляемая: не скрываем благодеяний Твоих, но громогласно объявляем, да все слышащие прибегают к Тебе, одной надежной Заступнице рода христианского, и да непрестанно прославляют Тебя, всеми Воспеваемую, во веки веков. Аминь."},
  {"id": "ru-mol-0008", "section": "service", "who": "rubric", "text": "Молитвы пред иконами Божией Матери"},
  {"id": "ru-mol-0009", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Акафистной»"},
  {"id": "ru-mol-0010", "section": "service", "who": "rubric", "text": "(25 января)"},
  {"id": "ru-mol-0011", "section": "service", "who": "rubric", "text": "О Пречудная и Превысшая всех тварей Царице и Богородице, Небеснаго Царя Христа Бога нашего Мати, припадаем и поклоняемся Тебе пред святою и пречестною иконою Твоею, еюже дивныя и преславныя чудеса содеваеши!"},
  {"id": "ru-mol-0012", "section": "service", "who": "reader", "text": "Перевод: О Предивная и Превысшая всех созданий Царица и Богородица, Небесного Царя Христа Бога нашего Матерь, припадаем и поклоняемся Тебе перед святой и чтимой иконой Твоей, которой удивительные и преславные чудеса совершаешь!"},
  {"id": "ru-mol-0013", "section": "service", "who": "reader", "text": "Смиренно молим Тебя, всемогущественная рода нашего Заступница, услышь нас и яви на нас обильные дары, и прошения наши, возносимые Тебе, как благая Скоропослушница, исполни. Благодатью Твоей души наши освяти и не отними от нас покровительства Твоего, под ним же всегда пребывая, как Стеной Нерушимой защищены останемся от всех бед и искушений, от всякого недруга и противника, от всех злых козней неприятельских на нас всегда надвигающихся."},
  {"id": "ru-mol-0014", "section": "service", "who": "reader", "text": "Благоуханием непорочной души Своей наполни души наши, да возрадуются сердца наши, ибо нет никого в мире этом ближе к сердцу и прекраснее Тебя, Дева Пресвятая! Ты – наше Богатство, Ты – наше Сокровище, Ты – наша Надежда и наша Защита! К Тебе Одной в скорбях наших прибегаем и у Тебя Одной утешение получить надеемся."},
  {"id": "ru-mol-0015", "section": "service", "who": "reader", "text": "О всеми Воспеваемая Дева Богородица, не переставай молиться о нас, недостойных рабах Твоих, прославляющих Тебя и почитающих, и надежду на Тебя полагающих, ныне и всегда и во веки веков. Аминь."},
  {"id": "ru-mol-0016", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Ахтырской»"},
  {"id": "ru-mol-0017", "section": "service", "who": "rubric", "text": "(15 июля)"},
  {"id": "ru-mol-0018", "section": "service", "who": "rubric", "text": "О Преблагословенная и Многомилостивая Владычице мира! Се мы грешнии на святый образ Твой взирающе и на нем Тя в скорби и сострадании распятому за нас Христу Спасителю предстоящу видяще, усердно молим Тя известную о нас к Сыну Твоему молитвенницу: не остави нас в день испытания и скорби, но во искушениих и напастех нам бываемых огради нас всечестным покровом Твоим от враг видимых и невидимых и даждь нам силу, во еже всесовершенную и благую волю Творца и мира Владыки творити."},
  {"id": "ru-mol-0019", "section": "service", "who": "reader", "text": "Перевод: О Преблагословенная и Многомилостивая Владычица мира! Вот мы, грешные, на святой образ Твой взирая и на нем Тебя в муках и сострадании распятому за нас Христу Спасителю стоящую видя, ревностно молим Тебя, постоянную о нас к Сыну Твоему молитвенницу: не оставь нас в день испытания и скорби, но в испытаниях и искушениях с нами происходящих огради нас почитаемым покровительством Твоим от врагов видимых и невидимых и дай нам силу, чтобы во всем совершенную и благую волю Творца и мира Владыки исполнять."},
  {"id": "ru-mol-0020", "section": "service", "who": "reader", "text": "Ибо видишь, милостивая Заступница наша, насколько грехам всяческим подвержены, потому что не только добровольно согрешаем, но и невольно в разнообразные прегрешения впадаем. Поэтому к Тебе могущественной устроительнице спасения христианского прибегаем и в сердечном сокрушении взываем: ум наш познанием Божественной истины просвети, сердце наше пылом христианской любви и спасительных устремлений согревай, волю же нашу в нелицемерном исполнении заповедей Господних укрепи."},
  {"id": "ru-mol-0021", "section": "service", "who": "reader", "text": "О Госпожа Премилостивая, снизойди с высоты Небесной к прошению и стонам нас, грешных: исцели болезни недужных, умиротвори сердца озлобленных, подай терпение страдающим, внуши страх Божий обидчикам, укрепи гонимых за правду, сирот и вдов защити, подай утешение плачущим, испроси прощение кающимся, демонскую же бурю страстей в грешных душах прекрати и в сердцах почитающих Тебя Христову кротость и любовь утверди и духом милосердия и сострадания их укрепи; отпавших же от веры еретиков и отступников к познанию истины направь и уста беззаконников, хулящих Святую Церковь и веру православную поносящих загради."},
  {"id": "ru-mol-0022", "section": "service", "who": "reader", "text": "Отошедшим от жизни этой отцам и братьям и сестрам нашим, о Матерь Божья, прощение грехов и предначинание блаженства вечного испроси. Когда же и нашей кончины час приблизится, тогда же, о Владычица, прими душу нашу и в сонме праведных ее упокой там, где хоры Ангелов и святых угодников не умолкая прославляют владычество и милость Отца и Сына и Святого Духа и Твое материнское о нас заступничество и защиту, ныне и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0023", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Барской»"},
  {"id": "ru-mol-0024", "section": "service", "who": "rubric", "text": "(14 октября)"},
  {"id": "ru-mol-0025", "section": "service", "who": "rubric", "text": "Богопрославленная, всемирно воспеваемая Госпоже Мати Вседержителева Богородице Марие! Приими нашу сию от полноты сердец любящих Тя, приносимую Тебе пред святою Твоею иконою молитву."},
  {"id": "ru-mol-0026", "section": "service", "who": "reader", "text": "Перевод: Богом прославленная, всемирно воспеваемая Госпожа Матерь Вседержителя Богородица Мария! Прими эту нашу от полноты сердец, любящих Тебя, приносимую Тебе перед святой Твоей иконой, молитву."},
  {"id": "ru-mol-0027", "section": "service", "who": "reader", "text": "Так же как до этого дня и часа милостиво покровительствовала всем людям, приходящим в храм этот, так и впредь способствуй нам во всех делах и начинаниях наших, которые не препятствуют нашему вечному спасению."},
  {"id": "ru-mol-0028", "section": "service", "who": "reader", "text": "Ты знаешь немощь нашу, видишь муки, беды и потрясения отовсюду нападающие, но все это можешь одним только Твоим взором умиротворить, если только захочешь помочь нам. Знаем, что из-за наших грехов недостойны мы милосердия Твоего, но Ты, Родившая Пришедшего в мир грешников спасти, спаси и нас во всякий день и час согрешающих."},
  {"id": "ru-mol-0029", "section": "service", "who": "reader", "text": "Укрепи слабую волю и немощное устремление наше и оживи нас духом истинного покаяния. Да таким образом очищены здесь Твоего покровительства удостоены будем и с горящими светильниками добродетелей в Страну Небесную перейдем беспрепятственно, где же удостоимся поклониться Тебе, Пречистая Госпожа, прославляя избравшую и возвеличившую Тебя Пресвятую Троицу, Отца и Сына, и Святого Духа во веки веков. Аминь."},
  {"id": "ru-mol-0030", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Балыкинской» («Волынской»)»"},
  {"id": "ru-mol-0031", "section": "service", "who": "rubric", "text": "(13 июля)"},
  {"id": "ru-mol-0032", "section": "service", "who": "rubric", "text": "О Мати Божия, некогда от нашествия иноверных свеев в велицей беде Отечеству нашему бывшу, явила еси всемощное заступление прославлением в стране Северстей всечестнаго образа Твоего, именуемаго Балыкинским, и зримыми на нем слезами очес Твоих умолила Сына Твоего и Бога нашего даровати православным Христианом преславную победу и одоление на супостаты."},
  {"id": "ru-mol-0033", "section": "service", "who": "reader", "text": "Перевод: О Матерь Божья, когда-то, когда от нашествия иноверных шведов в великой беде Отечество наше было, явила всемогущественное заступничество прославлением в стороне Северной особо почитаемого образа Твоего, именуемого Балыкинским, и видимыми на нем слезами очей Твоих умолила Сына Твоего и Бога нашего даровать православным христианам славную победу и одержать верх над врагами."},
  {"id": "ru-mol-0034", "section": "service", "who": "reader", "text": "Ты, Премилосердная Матерь, и в минувшие дни в городе Орле пред Пречистым образом Твоим даровала исцеление страдающей от духа нечистого девице, возвратив ее родителям здоровой и невредимой."},
  {"id": "ru-mol-0035", "section": "service", "who": "reader", "text": "Ты, скорая Помощница в бедах человеческих, услышала вопль матери ребенка, с высоты дома внезапно упавшего, и подняла его здоровым и невредимым."},
  {"id": "ru-mol-0036", "section": "service", "who": "reader", "text": "Ты, неиссякаемый источник чудес и милостей, принесенной к дивному образу Твоему отроковице полностью обездвиженной благоволила подать быстрое исцеление, укрепив ноги ее для вожделенного хождения."},
  {"id": "ru-mol-0037", "section": "service", "who": "reader", "text": "Ты, всемогущественная Царица неба и земли, подняла от неизлечимой болезни младенцев, родители которых прибегли к Тебе с верою и любовью."},
  {"id": "ru-mol-0038", "section": "service", "who": "reader", "text": "Ты, Подательница мира душам нашим, избавила юношу от лютейших страстей и переменила дурные наклонности его к чистой жизни и послушанию родителям."},
  {"id": "ru-mol-0039", "section": "service", "who": "reader", "text": "Ты обильно изливала струи Своей милости на всех, прибегающих к пресвятому образу Твоему в душевных скорбях, телесных недугах и житейских бедах."},
  {"id": "ru-mol-0040", "section": "service", "who": "reader", "text": "Внемли, о Всеблагая, и нынешнему ревностному молению нашему: направь пути земного странствия нашего к мирной и благодетельной жизни, упорядочи общество наше добрыми нравами, загради всесильною рукой Твоей уста лжеучителей, поднимающихся на Разум Божий, разрушающих обычаи православных предков наших и развращающих умы и сердца юных детей наших, пошли нам во вся дни жизни нашей чистоту помыслов и сердечных устремлений."},
  {"id": "ru-mol-0041", "section": "service", "who": "reader", "text": "Сама, о всеми Воспеваемая, защити и Тебе известными способами спаси и введи нас в радостные обители Сына Твоего и Бога нашего. Аминь."},
  {"id": "ru-mol-0042", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Белыничской»"},
  {"id": "ru-mol-0043", "section": "service", "who": "rubric", "text": "(25 апреля)"},
  {"id": "ru-mol-0044", "section": "service", "who": "rubric", "text": "О всемилостивая Госпоже Царице Богородице, от всех родов избранная и всеми роды земными и небесными ублажаемая! Припадаем, покланяемся Тебе и смиренно молим Тя: воззри милостиво на предстоящия пред святым образом Твоим чудотворным, и приими молитвы, со слезами Тебе приносимыя от нас, недостойных рабов Твоих, и к Твоему образу пение возсылаемое со умилением, яко Тебе Самой ту сущей, послушающей и подающей с верою просящим по коемуждо прошению исполнение."},
  {"id": "ru-mol-0045", "section": "service", "who": "reader", "text": "Перевод: О всемилостивая Госпожа Царица Богородице, от всех родов избранная и всеми родами земными и небесными ублажаемая! Припадаем, поклоняемся Тебе и смиренно просим Тебя: взгляни милостиво на стоящих перед святым образом Твоим чудотворным, и прими молитвы, со слезами Тебе приносимые от нас, недостойных рабов Твоих, и к Твоему образу молебное пение воссылаемое с сокрушением, как Тебе Самой здесь пребывающей, выслушивающей и подающей с верою просящим каждому прошения исполнение."},
  {"id": "ru-mol-0046", "section": "service", "who": "reader", "text": "Ты, именуемая Всех скорбящих Радость, услышь нас, скорбных. Ты, называемая Утоли мои печали, облегчи нашу печаль. Ты, Купина Неопалимая, сохрани мир и всех нас от вредоносных огненных стрел врага. Ты, Взыскание погибших (отыскание пропавших), не допусти нам погибнуть в бездне грехов наших. Ты, Одигитрия (Путеводительница), укажи нам истинный путь к спасению. Ты, Неувядаемый цвет чистоты, окажи нам помощь, обессиленным плотской страстью, и приведи нас к воздержанию. Ты, исполненная любви к Богу Скоропослушница, услышь в час этот молитву нашу."},
  {"id": "ru-mol-0047", "section": "service", "who": "reader", "text": "Ты, Заступница усердная, Матерь Господа Всевышнего, Ты, наша Матерь и надежда, облегчи скорбь нашу, ослабленным здоровье подари, обессиленных и больных исцели и от одра болезни подними. От бесноватых бесов отгони, притесняемых от бед избави, вдов защити, грешных прости, прокаженных очисти, слепым зрение подари, старых укрепи, юных научи, малых детей помилуй, бесплодных от бесплодия избавь, в семьях мир укрепи, путешествующим сопутствуй, православным христианам даруй победу и преобладание над врагами, ереси и расколы искорени, отпавших от благочестивой веры на путь истинный верни, страну нашу миром огради, земле плодородие даруй, всех же нас от внезапной смерти сохрани и все многообразные страсти исцели, потому что всё сможешь посредничеством к Сыну Твоему Христу Богу нашему. О всеми Воспеваемая Матерь, Пресвятая Дева Богородица, не переставай молиться о нас, недостойных, и к пречистому образу Твоему с сокрушением припадающих и со страхом и любовью на него взирающих, как на Тебя живую. Услышь нас, Владычица, на одну Тебя после Бога надеющихся."},
  {"id": "ru-mol-0048", "section": "service", "who": "reader", "text": "Ранее отошедших отцов и матерей, братьев и сестер наших упокой в селениях святых, в месте светлом, в месте блаженном, в месте отрадном, где нет горя и стенания. Когда же подойдет и наше от жизни этой отхождение и к вечной жизни переселение, позаботься о нас, преблагословенная надежда наша, подай нам христианскую кончину жизни нашей, безболезненную, непостыдную, мирную и Святых Тайн приобщенную, да в будущей жизни удостоимся все вместе со всеми святыми бесконечной блаженной жизни в Царстве возлюбленного Сына Твоего Иисуса Христа, Которому подобает всяческое прославление, почитание и поклонение со Безначальным Его Отцом и Пресвятым, и Благим, и Животворящим Его Духом ныне и всегда и во веки веков. Аминь."},
  {"id": "ru-mol-0049", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Благодатное Небо»"},
  {"id": "ru-mol-0050", "section": "service", "who": "rubric", "text": "(19 марта)"},
  {"id": "ru-mol-0051", "section": "service", "who": "rubric", "text": "Что Тя наречем, о, Благодатная Богомати Богоотроковице, Пренепорочная Марие? Киими песнопении возвеличим Тя, возвеличенную Небом и землею, Ангелами и человеки? Явися бо на Тебе неслышанное от века на земли и несведомое Ангелами на Небеси таинство, паче ума и слова, вочеловечения Бога Слова, рожденнаго съискони от Безначальнаго Отца без матери и воплощеннаго в Твоей утробе и с нетленною печатию девства Твоего родившагося."},
  {"id": "ru-mol-0052", "section": "service", "who": "reader", "text": "Перевод: Как Тебя назовем, о Благодатная Богоматерь Богоотроковица, Пренепорочная Мария? Какими песнопениями прославим Тебя, прославленную Небом и землею, ангелами и людьми? Открылось на Тебе неслыханное от начала мира на земле и неизвестное ангелам на Небесах таинство, превосходящее понимание и разум, вочеловечения Бога Слова, рожденного в начале от Безначального Отца без матери и воплощенного в Твоей утробе и с неразрушимой печатью девства Твоего родившегося."},
  {"id": "ru-mol-0053", "section": "service", "who": "reader", "text": "О, чудо всех давних и новых чудес! Неизменное слово Самого Бога о победоносном семени жены и исполнилось и осуществилось в Безмужней Деве. О, неизмеримая глубина премудрости и величия Божья!"},
  {"id": "ru-mol-0054", "section": "service", "who": "reader", "text": "Каким именем назовем Тебя, Невеста, брака не познавшая? Зарею ли назовем Тебя восходящего на небе солнца? Но Ты – само Небо, ибо из Тебя воссияло Солнце Правды – Христос Бог наш, Спаситель грешных."},
  {"id": "ru-mol-0055", "section": "service", "who": "reader", "text": "Называем ли Тебя вратами, вводящими в потерянный прародителями рай, изобиловавший всеми благами? Но Ты Сама – благодатный рай, произрастивший Цветок бессмертия, исцеляющий и отгоняющий смердение греха и зловоние прародительской смертности."},
  {"id": "ru-mol-0056", "section": "service", "who": "reader", "text": "Назовем ли Тебя юной Непорочной Девой, не познавшей брака? Но Ты и до старости оставалась Не познавшей брака и чистой до рождения, и в рождении, и после рождения Сына осталась."},
  {"id": "ru-mol-0057", "section": "service", "who": "reader", "text": "Назовем ли Тебя Чистой и Святой Марией, превзошедшей Своей чистотой всех матерей и прародительниц? Но Ты не только родила Того Младенца Христа, но и носила Его у Своей груди, и кормила Твоим материнским девическим молоком, Того, Который кормит всякое создание, Которому со страхом и трепетом предстоят Ангельские чины и Которого благодарит всё дышащее, и всё сотворенное."},
  {"id": "ru-mol-0058", "section": "service", "who": "reader", "text": "О, поистине Ты удивительная между женами, необычайная среди дев, неподражаемая среди матерей! К Тебе перед Твоим Божественным ликом припадаем и пред Твоими святыми стопами низвергаем и складываем все наши мысли, стремления, намерения и чувства. Освяти их Твоим Богоматерним сочувствием и вознеси их, как жертву нашего смиренного сердца, как малоценную лепту нашей духовной нищеты, к Престолу Сына Твоего, Спасителя нашего, да какими знает способами направит наш путь к спасению и наследованию Царства Его, не имеющего конца во веки веков. Аминь."},
  {"id": "ru-mol-0059", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Благоуханный Цвет»"},
  {"id": "ru-mol-0060", "section": "service", "who": "rubric", "text": "(28 ноября)"},
  {"id": "ru-mol-0061", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже Владычице Богородице! Вышши еси всех Ангел и Архангел, и всея твари честнейшая, Помощница еси обидимых, ненадеющихся надеяние, убогих Заступнице, печальных утешение, алчущих кормительнице, нагих одеяние, больных исцеление, грешных спасение, христиан всех поможение и заступление!"},
  {"id": "ru-mol-0062", "section": "service", "who": "reader", "text": "Перевод: О Пресвятая Госпожа Владычица Богородица! Ты выше всех ангелов и архангелов, и всех творений славнейшая, Помощница притесняемых, потерявших надежду надежда, бедных Заступница, скорбных утешение, голодных кормительница, нагих одеяние, больных исцеление, грешных спасение, христиан всех помощь и заступничество!"},
  {"id": "ru-mol-0063", "section": "service", "who": "reader", "text": "О Всемилостивая Госпожа, Дева Богородица Владычица, милостью Твоей спаси и помилуй Богохранимую страну нашу, власти и воинство ее, и всех православных христиан, ризой Твоей почитаемой защити: и умоли, Госпожа, из Тебя бессеменно воплотившегося Христа Бога нашего, да облечет нас силою Своею свыше на невидимых и видимых врагов наших."},
  {"id": "ru-mol-0064", "section": "service", "who": "reader", "text": "О Всемилостивая Госпожа, Владычица Богородица, подними нас из бездны греховной и избавь нас от голода, истребления, от землетрясения и потопа, от огня и меча, от нашествия иноплеменников и междоусобной войны, и от внезапной смерти, и от нападения вражеского (дьявольского), и от опустошительных ветров, и от смертоносных ран, и от всякого зла."},
  {"id": "ru-mol-0065", "section": "service", "who": "reader", "text": "Подай, Госпожа, покой и здоровье рабам Твоим, всем православным христианам, и просвети им ум и духовное зрение для спасения: и удостой нас, грешных рабов Твоих, Царства Сына Твоего, Христа Бога нашего: потому что власть Его благословенна, и прославлена, со Безначальным Его Отцом, и с Пресвятым, и Благим, и Животворящим Его Духом, ныне и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0066", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Боголюбской»"},
  {"id": "ru-mol-0067", "section": "service", "who": "rubric", "text": "(1 июля)"},
  {"id": "ru-mol-0068", "section": "service", "who": "rubric", "text": "О Пречистая Госпоже Богородице, Мати Боголюбивая, надеждо нашего спасения! Воззри милостивно на предстоящия с верою и любовию и покланяющияся пречистому образу Твоему; приими наше хвалебное пение сие и пролей теплую Твою молитву о нас грешных ко Господу, да, презрев вся наша согрешения, спасет и помилует нас!"},
  {"id": "ru-mol-0069", "section": "service", "who": "reader", "text": "Перевод: О Пречистая Госпожа Богородица, Матерь Боголюбивая, надежда нашего спасения! Взгляни милостиво на предстоящих с верой и любовью и поклоняющихся пречистому образу Твоему; прими это наше хвалебное пение и излей горячую Твою молитву о нас грешных к Господу, да, несмотря на наши согрешения, спасет и помилует нас!"},
  {"id": "ru-mol-0070", "section": "service", "who": "reader", "text": "О Предивная Владычица! Яви на нас удивительные милости Твои. Молим тебя сокрушенно: избавь нас от всякой беды, наставь на путь всяческих добродетелей и блага, спаси от искушений, бед и болезней, избавь нас от клеветы и ссор, сохрани от молниеносного грома, от пожара огненного, от голода, землетрясения, потопа и смертельной раны; подай нам Свою милостивую помощь в путешествии, в море и на суше, чтобы не погибли жестоко."},
  {"id": "ru-mol-0071", "section": "service", "who": "reader", "text": "О Всемилостивая Боголюбивая Матерь, с несомненной надеждой воссылаем к Тебе нашу смиренную молитву! Не отвергни слез наших и стенаний, не забудь нас во все дни жизни нашей, но всегда будь с нами, и Твоим заступничеством и посредничеством у Господа подай нам облегчение, утешение, защиту и помощь, да всегда прославляем и величаем Преблагословенное и всеми Воспеваемое имя Твое. Аминь."},
  {"id": "ru-mol-0072", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Валаамской»"},
  {"id": "ru-mol-0073", "section": "service", "who": "rubric", "text": "(воскресенье после 12 июля)"},
  {"id": "ru-mol-0074", "section": "service", "who": "rubric", "text": "О Чудная и вышшая всех тварей Царице Богородице, Небеснаго Царя Христа Бога нашего Мати! Услыши ны грешныя и недостойныя рабы Твоя, в час сей молящияся и припадающия к Тебе со воздыханием и слезами и умильно глаголющия: изведи нас от рова страстей, Владычице, избави нас от всякия скорби и печали, огради от всякия напасти и злых клевет и от неправеднаго и лютаго навета вражия."},
  {"id": "ru-mol-0075", "section": "service", "who": "reader", "text": "Перевод: О Дивная и высшая всех созданий Царица Богородице, Небесного Царя Христа Бога нашего Матерь! Услышь нас грешных и недостойных рабов Твоих, в час этот молящихся и припадающих к Тебе со стенаниями и слезами и смиренно произносящих: выведи нас из пропасти прегрешений, Владычица, избавь нас от всяческой скорби и горя, огради от всяческих бед и злобной клеветы и от несправедливых и страшных козней вражеских."},
  {"id": "ru-mol-0076", "section": "service", "who": "reader", "text": "Потому что можешь, о Благодатная Матерь Божья, не только от любого зла уберечь людей Твоих, но и всякими благодеяниями сохранить их и спасти, кроме Тебя нет иной Защитницы в бедах и напастях и горячей Просительницы за нас грешных к Сыну Твоему, Христу Богу нашему. Его умоли, Владычица, чтобы, спасённые Тобой, славили в будущей жизни всесвятое имя Сына Твоего и Бога нашего, вместе с Отцом и Святым Духом, ныне и бесконечно. Аминь."},
  {"id": "ru-mol-0077", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери Ватопедской, именуемой «Отрада» или «Утешение»"},
  {"id": "ru-mol-0078", "section": "service", "who": "rubric", "text": "(3 февраля)"},
  {"id": "ru-mol-0079", "section": "service", "who": "rubric", "text": "Надежда всем концем земли, Пречистая Дево Богородице, Утешение и Отрадо наше! Не гнушайся нас грешных, на Твою бо1 милость уповаем."},
  {"id": "ru-mol-0080", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Взыскание погибших»"},
  {"id": "ru-mol-0081", "section": "service", "who": "rubric", "text": "(18 февраля)"},
  {"id": "ru-mol-0082", "section": "service", "who": "rubric", "text": "О Пресвятая и Преблагословенная Дево, Владычице Богородице, Споручнице9 грешных и Взыскание погибших10! Призри11 милостивным Твоим оком на нас, предстоящих пред святою иконою Твоею и со умилением12 молящихся Тебе: воздвигни нас из глубины греховныя, просвети ум наш, омраченный страстьми13, и уврачуй язвы душ и телес наших."},
  {"id": "ru-mol-0083", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Владимирской»"},
  {"id": "ru-mol-0084", "section": "service", "who": "rubric", "text": "(3 июня, 6 июля и 8 сентября)"},
  {"id": "ru-mol-0085", "section": "service", "who": "rubric", "text": "О Всемилостивая Госпоже Богородице, Небесная Царице, всемощная22 Заступнице, непостыдное наше упование! Благодарим Тя о всех благодеяниих, российским людем от Тебе бывших, отдревле23 и доднесь24 от чудотворныя иконы Твоея явленных."},
  {"id": "ru-mol-0086", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Владимирской-Елецкой»"},
  {"id": "ru-mol-0087", "section": "service", "who": "rubric", "text": "(8 сентября)"},
  {"id": "ru-mol-0088", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже Владычице Богородице! Вышши35 еси всех Ангел и Архангел и всея твари честнейши36, помощница еси обидимых, ненадеющихся надеяние37, убогих заступница, печальных утешение, алчущих кормительница, нагих одеяние, больных исцеление, грешных спасение, христиан всех поможение и заступление."},
  {"id": "ru-mol-0089", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Воспитание»"},
  {"id": "ru-mol-0090", "section": "service", "who": "rubric", "text": "(18 марта)"},
  {"id": "ru-mol-0091", "section": "service", "who": "rubric", "text": "О, Пресвятая Владычице Дево Богородице, спаси и сохрани под кровом Твоим чад моих (имена их), всех отроков, отроковиц и младенцев, крещеных и безымянных и во чреве матере носимых. Покрый их ризою Твоего Материнства, соблюди их во страсе40 Божием и в послушании родителем, умоли Сына Твоего и Господа нашего, да дарует им полезная ко спасению их. Вручаю их Матернему смотрению41 Твоему, яко Ты еси Божественный покров рабом Твоим. Аминь."},
  {"id": "ru-mol-0092", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Всех скорбящих Радость»"},
  {"id": "ru-mol-0093", "section": "service", "who": "rubric", "text": "(6 ноября)"},
  {"id": "ru-mol-0094", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице и Богородице, высшая Херувим и честнейшая Серафим, Богоизбранная Отроковице, всех скорбящих Радосте!"},
  {"id": "ru-mol-0095", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Всеблаженной»"},
  {"id": "ru-mol-0096", "section": "service", "who": "rubric", "text": "(14 сентября)"},
  {"id": "ru-mol-0097", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Господа Вышних сил, Небесе и земли Царице, града и страны нашея всемощная Заступнице! Приими хвалебное пение сие от нас недостойных раб Твоих, и вознеси молитвы наша ко престолу Бога Сына Твоего, да милостив будет неправдам нашим и пробавит45 благодать Свою чтущим всечестное имя Твое и с верою и любовию покланяющимся пречистому образу Твоему."},
  {"id": "ru-mol-0098", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Всецарица»"},
  {"id": "ru-mol-0099", "section": "service", "who": "rubric", "text": "(31 августа)"},
  {"id": "ru-mol-0100", "section": "service", "who": "rubric", "text": "О Пречистая Богомати, Всецарице! Услыши многоболезненное воздыхание наше пред чудотворною иконою Твоею, из удела Афонскаго в Россию принесенною, призри на чад Твоих, неисцельными недуги страждущих, ко святому Образу Твоему с верою припадающих!"},
  {"id": "ru-mol-0101", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «В скорбех и печалех Утешение»"},
  {"id": "ru-mol-0102", "section": "service", "who": "rubric", "text": "(2 декабря)"},
  {"id": "ru-mol-0103", "section": "service", "who": "rubric", "text": "К кому возопию, Владычице? К кому прибегну в горести моей, аще не к Тебе, Царице Небесная? Кто плач мой и воздыхание мое приимет, аще не Ты, Пренепорочная, Надеждо христиан и Прибежище нам, грешным? Кто паче49 Тебе в напастех защитит?"},
  {"id": "ru-mol-0104", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Грузинской» (Красногорской)»"},
  {"id": "ru-mol-0105", "section": "service", "who": "rubric", "text": "(4 сентября)"},
  {"id": "ru-mol-0106", "section": "service", "who": "rubric", "text": "Приими, Всеблагомощная51 Пречистая Госпоже, Владычице Богородительнице, сия честныя52 дары от нас, недостойных рабов Твоих, к Твоему цельбоносному образу пение возсылающих со умилением, яко Тебе Самой сущей ту и послушающей моления наша, подающи с верою просящим по коемуждо53 прошению исполнение: скорбящим скорби облегчаеши, немощным здравие даруеши, разслабленных и недужных исцеляеши, и от бесных бесы прогоняеши, обидимыя от обид избавляеши, и насилуемых спасаеши, грешных прощаеши, прокаженных очищаеши, и малых детей милуеши, и неплодныя от неплодства разрешаеши."},
  {"id": "ru-mol-0107", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Державной»"},
  {"id": "ru-mol-0108", "section": "service", "who": "rubric", "text": "(15 марта)"},
  {"id": "ru-mol-0109", "section": "service", "who": "rubric", "text": "О мира Заступнице, Мати Всепетая! Со страхом, верою и любовию припадающе пред честною иконою Твоею Державною, усердно молим Тя: не отврати лица Твоего от прибегающих к Тебе. Умоли, милосердая Мати Света, Сына Твоего и Бога нашего, сладчайшаго57 Господа Иисуса Христа: да сохранит в мире страну нашу, да утвердит державу нашу во благоденствии и избавит нас от междоусобныя брани; да укрепит Святую Церковь нашу Православную и незыблему соблюдет ю58 от неверия, раскола и ересей."},
  {"id": "ru-mol-0110", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Донской»"},
  {"id": "ru-mol-0111", "section": "service", "who": "rubric", "text": "(1 сентября)"},
  {"id": "ru-mol-0112", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице, Дево Богородице, Заступнице наша благая и скорая! Воспеваем Ти вси благодарственная за чудная дела Твоя. Песнословим от лет древних неотъемлемое заступление Твое граду Москве и стране нашей, чудотворным Образом Твоим Донским всегда являемое: в бегство обращаются полки чуждих, грады и веси невредими сохраняются, людие же от лютыя смерти избавляются. Осушаются очи слезящия, умолкают стенания верных, плач в радость общую претворяется60."},
  {"id": "ru-mol-0113", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Елецкой-Черниговской»"},
  {"id": "ru-mol-0114", "section": "service", "who": "rubric", "text": "(18 февраля)"},
  {"id": "ru-mol-0115", "section": "service", "who": "rubric", "text": "Премилосердая наша Заступнице, и душ наших благая Хранительнице, и телес наших милосердая Целительнице, Богородице Дево!"},
  {"id": "ru-mol-0116", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Живоносный источник»"},
  {"id": "ru-mol-0117", "section": "service", "who": "rubric", "text": "(пятница Светлой седмицы)"},
  {"id": "ru-mol-0118", "section": "service", "who": "rubric", "text": "Царице моя преблагая, надеждо моя Богородице, прибежище сирых69 и странных70 Предстательнице, скорбящих радосте, обидимых Покровительнице!"},
  {"id": "ru-mol-0119", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Жировицкой»"},
  {"id": "ru-mol-0120", "section": "service", "who": "rubric", "text": "(20 мая)"},
  {"id": "ru-mol-0121", "section": "service", "who": "rubric", "text": "О Премилосердная Госпоже, Дево Богородице! Киима73 устнама прикоснуся ко святыни Твоей, или киими словесы исповем щедроты Твоя, людем являемыя: никтоже бо, притекаяй к Тебе, отходит тощ и не услышан."},
  {"id": "ru-mol-0122", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Знамение» Абалакская»"},
  {"id": "ru-mol-0123", "section": "service", "who": "rubric", "text": "(2 августа, 10 декабря)"},
  {"id": "ru-mol-0124", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице моя Богородице, милосердия сущи источник, покрове, упование и прибежище христиан! Тебе, Всесильней Предстательнице и Споручнице покаяния и спасения моего, аз, грешный раб Твой, вручаю душу и тело мое, входы и исходы75 моя, веру и жительство мое, кончину и число дней моих, глаголы и помышления моя, дела и начинания моя."},
  {"id": "ru-mol-0125", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Знамение» Корчемная»"},
  {"id": "ru-mol-0126", "section": "service", "who": "rubric", "text": "(10 декабря)"},
  {"id": "ru-mol-0127", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице Богородице, Небеснаго Царя Мати, Богоизбранная Отроковице! Ненадежных надеяние, больных исцеление, сирым предстательнице, скорбящим утешение и радость, обидимым покровительнице и всем в бедах и напастях сущим скорое поможение и заступление!"},
  {"id": "ru-mol-0128", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Знамение» Курская-Коренная»"},
  {"id": "ru-mol-0129", "section": "service", "who": "rubric", "text": "(10 декабря, 21 марта, 21 сентября)"},
  {"id": "ru-mol-0130", "section": "service", "who": "rubric", "text": "О Царице Небесная! Кто изочтет великое множество чудес Твоих, кто исчислит вопли молитвенных прошений, токи умиленных слез, благодарных воздыханий, пролитых пред иконою Твоею."},
  {"id": "ru-mol-0131", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Знамение» Новгородская»"},
  {"id": "ru-mol-0132", "section": "service", "who": "rubric", "text": "(10 декабря)"},
  {"id": "ru-mol-0133", "section": "service", "who": "rubric", "text": "О Пресвятая и Преблагословенная Мати Сладчайшаго Господа нашего Иисуса Христа! Припадаем и поклоняемся Тебе пред святою чудотворною иконою Твоею, воспоминающе дивное знамение Твоего заступления, великому Новуграду от нея явленное во дни ратнаго на сей град нашествия."},
  {"id": "ru-mol-0134", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Иверской»"},
  {"id": "ru-mol-0135", "section": "service", "who": "rubric", "text": "(26 октября, 25 февраля и во вторник Светлой седмицы)"},
  {"id": "ru-mol-0136", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Господа, Царице Небесе и земли! Вонми многоболезненному воздыханию душ наших, призри с высоты святыя Твоея на нас, с верою и любовию покланяющихся пречистому образу Твоему."},
  {"id": "ru-mol-0137", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Иерусалимской»"},
  {"id": "ru-mol-0138", "section": "service", "who": "rubric", "text": "(25 октября)"},
  {"id": "ru-mol-0139", "section": "service", "who": "rubric", "text": "Пресвятая Госпоже, Владычице Богородице, упование всех уповающих на Тя, Заступнице печальных, прибежище отчаянных, вдов и сирот Питательнице!"},
  {"id": "ru-mol-0140", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Избавительница»"},
  {"id": "ru-mol-0141", "section": "service", "who": "rubric", "text": "(30 октября, 30 апреля)"},
  {"id": "ru-mol-0142", "section": "service", "who": "rubric", "text": "О, Мати Божия, помоще и защита наша, егда попросим, буди избавительнице наша, на Тя бо уповаем и всегда вседушно Тя призываем: умилосердися и помози, пожалей и избави, приклони ухо Твое и наши скорбныя и слезныя молитвы приими, и якоже хощеши, успокой и обрадуй нас, любящих твоего Безначального Сына и Бога нашего. Аминь."},
  {"id": "ru-mol-0143", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Избавление от бед страждущих»"},
  {"id": "ru-mol-0144", "section": "service", "who": "rubric", "text": "(30 июня)"},
  {"id": "ru-mol-0145", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Казанской»"},
  {"id": "ru-mol-0146", "section": "service", "who": "rubric", "text": "(4 ноября и 21 июля)"},
  {"id": "ru-mol-0147", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже Владычице Богородице! Со страхом, верою и любовию пред честною (и чудотворною) иконою Твоею припадающе, молим Тя: не отврати лица Твоего от прибегающих к Тебе."},
  {"id": "ru-mol-0148", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Калужской»"},
  {"id": "ru-mol-0149", "section": "service", "who": "rubric", "text": "(25 октября, 31 июля, 15 сентября)"},
  {"id": "ru-mol-0150", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Христа Бога нашего, Дивная Царице Небесе и земли! Вонми многоболезненному воздыханию сердец наших; призри с высоты святыя Твоея на нас, с верою и любовию предстоящих пред чудотворною Твоею иконою и со умилением молящихся Тебе, Владычице!"},
  {"id": "ru-mol-0151", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Киево-Братской»"},
  {"id": "ru-mol-0152", "section": "service", "who": "rubric", "text": "(23 мая, 15 июня, 19 сентября)"},
  {"id": "ru-mol-0153", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже, Пречистая Владычице Богородице. Призри Всемилостивым Твоим оком на нас, предстоящих пред пречистым Твоим образом, Киево-Братским нарицающимся, и молящихся Ти пред ним."},
  {"id": "ru-mol-0154", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Коневской»"},
  {"id": "ru-mol-0155", "section": "service", "who": "rubric", "text": "(23 июля)"},
  {"id": "ru-mol-0156", "section": "service", "who": "rubric", "text": "О Всемилостивая Госпоже, Дево Богородице! Вонми смиренному молению моему, и сокрушенно ныне предстоящаго образу Твоему услыши глас."},
  {"id": "ru-mol-0157", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Купятицкой»"},
  {"id": "ru-mol-0158", "section": "service", "who": "rubric", "text": "(28 ноября)"},
  {"id": "ru-mol-0159", "section": "service", "who": "rubric", "text": "О Преблагословенная Владычице, всемощная Заступнице, непостыдное наше Упование! Приими хвалебное и благодарственное пение нас, недостойных раб Твоих, и вознеси молитвы наша ко Престолу Сына и Бога Твоего, да милостив будет неправдам нашим, пробавит благость Свою чтущим Всечестное имя Твое и с верою и любовию поклоняющимся чудотворному образу Твоему."},
  {"id": "ru-mol-0160", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Любечской»"},
  {"id": "ru-mol-0161", "section": "service", "who": "rubric", "text": "(20 мая)"},
  {"id": "ru-mol-0162", "section": "service", "who": "rubric", "text": "О, Пресвятая и Преблагословенная Мати Господа и Спаса нашего Иисуса Христа, Пречистая Приснодево, Богородице Марие! Припадаем и покланяемся Тебе пред святою и чудотворною иконою Твоею, юже от лет древних зде чудесы многими и исцеленьми неисчетными прославити благоизволила еси."},
  {"id": "ru-mol-0163", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Максимовской»"},
  {"id": "ru-mol-0164", "section": "service", "who": "rubric", "text": "(1 мая)"},
  {"id": "ru-mol-0165", "section": "service", "who": "rubric", "text": "Нескверная, неблазная76, нетленная, Пречистая, Чистая Дево, Богоневесто Владычице, яже Бога Слова человеком преславным Твоим рождеством соединившая, и отринувшееся естество рода нашего Небесным совокупльшая, яже ненадежных едина надеждо и боримых помоще, готовое заступление к Тебе притекающих и всех христиан прибежище!"},
  {"id": "ru-mol-0166", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Мариупольской»"},
  {"id": "ru-mol-0167", "section": "service", "who": "rubric", "text": "(28 августа)"},
  {"id": "ru-mol-0168", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже, Царице небесе и земли, Преблагословенная Мати Христа Бога нашего! С верою и любовию молитвенно прибегаем мы недостойнии к Тебе, Пречистая Заступнице наша."},
  {"id": "ru-mol-0169", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Милостивая»"},
  {"id": "ru-mol-0170", "section": "service", "who": "rubric", "text": "(25 ноября, 8 января)"},
  {"id": "ru-mol-0171", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Милующая», или «Достойно есть»"},
  {"id": "ru-mol-0172", "section": "service", "who": "rubric", "text": "(24 июня)"},
  {"id": "ru-mol-0173", "section": "service", "who": "rubric", "text": "О Пресвятая и Премилостивая Владычице Богородице! Припадающе ко святей иконе Твоей, смиренно молимся Тебе: вонми гласу моления нашего, виждь скорби, виждь беды наша, и яко любвеобильная Мати, потщися на помощь нам безпомощным: умоли Сына Твоего и Бога нашего, да не погубит нас за беззакония наша, но да явит нам человеколюбно Свою милость."},
  {"id": "ru-mol-0174", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Млекопитательница»"},
  {"id": "ru-mol-0175", "section": "service", "who": "rubric", "text": "(25 января)"},
  {"id": "ru-mol-0176", "section": "service", "who": "rubric", "text": "Приими, Госпоже Богородительнице, слезная моления рабов Твоих, к Тебе притекающих. Зрим Тя на святей иконе, на руках носящую и млеком питающую Сына Твоего и Бога нашего, Господа Иисуса Христа."},
  {"id": "ru-mol-0177", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Муромской»"},
  {"id": "ru-mol-0178", "section": "service", "who": "rubric", "text": "(25 апреля)"},
  {"id": "ru-mol-0179", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Господа Вышних сил, Небесе и земли Царице, града и страны нашея Всемощная Заступнице! Услыши нас, молящихся Тебе, и испроси у Бога Сына Твоего пастырем нашим ревность и бдение о душах, градоправителем – мудрость и силу, судиям – правду и нелицеприятие, наставником – разум и смиренномудрие, супругом – любовь и согласие, чадом – послушание, обидимым – терпение, обидящим — страх Божий, скорбящим – благодушие, радующимся – воздержание."},
  {"id": "ru-mol-0180", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Неопалимая Купина»"},
  {"id": "ru-mol-0181", "section": "service", "who": "rubric", "text": "(17 сентября)"},
  {"id": "ru-mol-0182", "section": "service", "who": "rubric", "text": "О Пресвятая и Преблагословенная Мати Сладчайшаго Господа нашего Иисуса Христа! Припадаем и поклоняемся Тебе пред святою и пречестною иконою Твоею, еюже дивны и преславны чудеса содеваеши, от огненнаго запаления и молниеноснаго грома жилища наша спасавши, недужныя исцеляеши и всякое благое прошение наше во благо исполняеши."},
  {"id": "ru-mol-0183", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Неувядаемый Цвет»"},
  {"id": "ru-mol-0184", "section": "service", "who": "rubric", "text": "(16 апреля)"},
  {"id": "ru-mol-0185", "section": "service", "who": "rubric", "text": "О Пресвятая и Пренепорочная Мати Дево, надеждо христиан и прибежище грешным! Защити всех в несчастиях к Тебе прибегающих, услыши стенания наша, приклони ухо Твое к молению нашему."},
  {"id": "ru-mol-0186", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Неупиваемая Чаша»"},
  {"id": "ru-mol-0187", "section": "service", "who": "rubric", "text": "(18 мая)"},
  {"id": "ru-mol-0188", "section": "service", "who": "rubric", "text": "О, Премилосердная Владычице! К Твоему заступлению ныне прибегаем, молений наших не презри, но милостиво услыши нас: жен, детей, матерей и тяжким недугом пианства одержимых, и того ради от матере своея, Церкве Христовой, и спасения отпадающих, братий и сестер и сродник наших исцели."},
  {"id": "ru-mol-0189", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Нечаянная Радость»"},
  {"id": "ru-mol-0190", "section": "service", "who": "rubric", "text": "(22 декабря и 14 мая)"},
  {"id": "ru-mol-0191", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Всеблагаго Сына Мати Всеблагая, царствующаго града и святаго храма сего Покрове, всех сущих во гресех и скорбех, бедах же и болезнех верная Предстательнице и Заступнице!"},
  {"id": "ru-mol-0192", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Одигитрия» Выдропусская»"},
  {"id": "ru-mol-0193", "section": "service", "who": "rubric", "text": "(10 августа)"},
  {"id": "ru-mol-0194", "section": "service", "who": "rubric", "text": "О Царице Небесе и земли, Владычице всемилостивая, Одигитрие85 всечестная, Предстательнице наша усердная, при Кресте Сына Твоего и Бога всыновившая весь падший род человеческий и по успении Своем не оставившая нас сирых и безнадежных!"},
  {"id": "ru-mol-0195", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Остробрамской Виленской»"},
  {"id": "ru-mol-0196", "section": "service", "who": "rubric", "text": "(8 января, 27 апреля)"},
  {"id": "ru-mol-0197", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Господа вышних сил, Небесе и земли Царице и града нашего Киева всемощная Заступнице!"},
  {"id": "ru-mol-0198", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «О Тебе радуется»"},
  {"id": "ru-mol-0199", "section": "service", "who": "rubric", "text": "(8 января)"},
  {"id": "ru-mol-0200", "section": "service", "who": "rubric", "text": "О Тебе радуется, Благодатная, всякая тварь, Ангельский собор и человеческий род, Освященный Храме и Раю Словесный, Девственная похвало, из Неяже Бог воплотися и Младенец бысть, прежде век Сый Бог наш. Ложесна бо Твоя Престол сотвори. И чрево Твое пространнее Небес содела. О Тебе радуется, Благодатная, всякая тварь, слава тебе."},
  {"id": "ru-mol-0201", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Пермской»"},
  {"id": "ru-mol-0202", "section": "service", "who": "rubric", "text": "(17 июля)"},
  {"id": "ru-mol-0203", "section": "service", "who": "rubric", "text": "О всепетая Богородице Приснодево, Богоизбранная Отроковице! Огради образом Своим чудотворным всю землю Пермскую и всех благочестно живущих на ней от всех наветов вражиих, защити чад своих земных материнским Покровом Своим, укрепи в вере и благочестии всех властей и воинство земли нашей, архипастырем земли Пермстей подаждь мудрость и кротость в несении креста своего, и подаждь нам, Владычице, силу служити ближним своим, и стране нашей подаждь стойкость в испытаниях и веру непоколебиму."},
  {"id": "ru-mol-0204", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Песчанской»"},
  {"id": "ru-mol-0205", "section": "service", "who": "rubric", "text": "(21 июля)"},
  {"id": "ru-mol-0206", "section": "service", "who": "rubric", "text": "О премилостивая и премилосердная Мати Божия, Покровительнице державы нашея, купно же и о всем мире Молитвеннице, приими сердца нашего воздыхания, и услыши коленопреклоненныя молитвы, во умилении душ наших Тебе возсылаемыя, якоже издревле приимала еси молитвы любящих душ зде, пред иконою Твоею возносимыя."},
  {"id": "ru-mol-0207", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Печерской»"},
  {"id": "ru-mol-0208", "section": "service", "who": "rubric", "text": "(16 мая)"},
  {"id": "ru-mol-0209", "section": "service", "who": "rubric", "text": "О Пресвятая и Пренепорочная Дево Богородице, наша Печерская похвало и украшение, державный покрове святаго места сего, истинная Владычице избраннаго удела Своего."},
  {"id": "ru-mol-0210", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Покров Пресвятой Богородицы»"},
  {"id": "ru-mol-0211", "section": "service", "who": "rubric", "text": "(14 октября)"},
  {"id": "ru-mol-0212", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Господа вышних сил, Небесе и земли Царице, града и страны нашея Всемощная Заступнице!"},
  {"id": "ru-mol-0213", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Попской»"},
  {"id": "ru-mol-0214", "section": "service", "who": "rubric", "text": "(25 января)"},
  {"id": "ru-mol-0215", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Преславная Госпоже Владычице наша Богородице, воззри милостиво на нас, предстоящих Ти с верою и любовию: приими милостиво наше хвалебное пение сие и пролей ко Господу Богу нашему Твою матернюю молитву о нас, грешных и недостойных, да узрит Он наше покаяние сердечное и, простив нам вся согрешения наша, спасет и помилует нас."},
  {"id": "ru-mol-0216", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Почаевской»"},
  {"id": "ru-mol-0217", "section": "service", "who": "rubric", "text": "(21 сентября и 5 августа)"},
  {"id": "ru-mol-0218", "section": "service", "who": "rubric", "text": "О Всемилостивая Госпоже, Царице и Владычице, от всех родов избранная и всеми роды Небесными и земными ублажаемая! Воззри милостивно на предстоящий пред святою иконою Твоею и усердно к Тебе молящийся народ сей, и сотвори предстательством и заступлением Твоим у Сына Твоего и Бога нашего, да никтоже изыдет отсюду упования своего тощ и посрамлен в надежде своей, но да приимет кийждо от Тебе вся, по благому изволению сердца своего и по нужде и потребе своей, во спасение души и во здравие телу."},
  {"id": "ru-mol-0219", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Прибавление ума»"},
  {"id": "ru-mol-0220", "section": "service", "who": "rubric", "text": "(воскресенье после 28 августа)"},
  {"id": "ru-mol-0221", "section": "service", "who": "rubric", "text": "Богородице Пречистая, доме, егоже созда Себе Премудрость Божия, даров духовных Подательнице, от мира к премирным ум наш возводящая и всех к познанию разума приводящая!"},
  {"id": "ru-mol-0222", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Призри на смирение»"},
  {"id": "ru-mol-0223", "section": "service", "who": "rubric", "text": "(29 сентября)"},
  {"id": "ru-mol-0224", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже, Дево Богородице, высшая Херувим и Честнейшая Серафим, Богоизбранная Отроковице!"},
  {"id": "ru-mol-0225", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Рудненской»"},
  {"id": "ru-mol-0226", "section": "service", "who": "rubric", "text": "(25 октября)"},
  {"id": "ru-mol-0227", "section": "service", "who": "rubric", "text": "Пресвятая Дево Владычице Богородице, милосте Христа моего, обителище Пресвятаго и Животворящаго Духа, надеждо всех святых раб, святое зерцало87 светлости Божия, святейшая Ангел и Архангел, Тебе припадая, усердно молюся: умоли Сына Своего и Бога моего, да отпустит ми всякое прегрешение, вольное и невольное, избавит мя от всех наветов диавольских."},
  {"id": "ru-mol-0228", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Скоропослушница»"},
  {"id": "ru-mol-0229", "section": "service", "who": "rubric", "text": "(22 ноября)"},
  {"id": "ru-mol-0230", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Господа Вышняго, скоропослушная Заступнице всех, к Тебе с верою прибегающих!"},
  {"id": "ru-mol-0231", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Смоленской»"},
  {"id": "ru-mol-0232", "section": "service", "who": "rubric", "text": "(10 августа)"},
  {"id": "ru-mol-0233", "section": "service", "who": "rubric", "text": "О, пречудная и превышшая всех тварей Царице Богородице, Небеснаго Царя Христа Бога нашего Мати, Пресвятая Одигитрие Марие!"},
  {"id": "ru-mol-0234", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «София – Премудрость Божия»"},
  {"id": "ru-mol-0235", "section": "service", "who": "rubric", "text": "(28 августа)"},
  {"id": "ru-mol-0236", "section": "service", "who": "rubric", "text": "Непостижимая и Всепетая Премудросте Божия, Софие Преименитая, девственных душе, сиречь90 Единородный Сыне, Слове Божий, приими молебное сие пение от недостойных и скверных уст наших."},
  {"id": "ru-mol-0237", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Спасительница утопающих» (Леньковская)"},
  {"id": "ru-mol-0238", "section": "service", "who": "rubric", "text": "(2 января)"},
  {"id": "ru-mol-0239", "section": "service", "who": "rubric", "text": "Заступница усердная, Мати Господа Вышняго! Ты еси всем христианом помощь и заступление, паче же в бедах сущим."},
  {"id": "ru-mol-0240", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Спорительница хлебов»"},
  {"id": "ru-mol-0241", "section": "service", "who": "rubric", "text": "(28 октября)"},
  {"id": "ru-mol-0242", "section": "service", "who": "rubric", "text": "О Пресвятая Дево Богородице, Премилостивая Владычице, Царице Небесе и земли, всякаго дома и семейства христианскаго Благоустроительнице, труждающихся благословение, нуждающихся неистощимое богатство, сирых и вдовиц и всех людей Кормительнице!"},
  {"id": "ru-mol-0243", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Споручница грешных»"},
  {"id": "ru-mol-0244", "section": "service", "who": "rubric", "text": "(20 марта, 11 июня)"},
  {"id": "ru-mol-0245", "section": "service", "who": "rubric", "text": "О Владычице Преблагословенная, Защитнице рода христианскаго, прибежище и спасение притекающих к Тебе!"},
  {"id": "ru-mol-0246", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Страстной»"},
  {"id": "ru-mol-0247", "section": "service", "who": "rubric", "text": "(26 августа)"},
  {"id": "ru-mol-0248", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже, Владычице Богородице, вышши еси всех Ангел и Архангел и всея твари честнейши, Помощница еси обидимых, ненадеющихся надеяние, убогих Заступница, печальных утешение, алчущих Кормительница, нагих одеяние, больных исцеление, грешных спасение, христиан всех поможение и заступление."},
  {"id": "ru-mol-0249", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Табынской»"},
  {"id": "ru-mol-0250", "section": "service", "who": "rubric", "text": "(9-я пятница после Пасхи)"},
  {"id": "ru-mol-0251", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице Богородице, Мати Господа нашего Иисуса Христа, непрестанная о нас пред Богом Молитвеннице и Ходатаице."},
  {"id": "ru-mol-0252", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Тихвинской»"},
  {"id": "ru-mol-0253", "section": "service", "who": "rubric", "text": "(9 июля)"},
  {"id": "ru-mol-0254", "section": "service", "who": "rubric", "text": "Благодарим Тя, о Преблагая и Пречистая, Преблагословенная Дево, Владычице, Мати Христа Бога нашего, о всех благодеяниих Твоих, яже показала еси роду человеческому, наипаче же нам, христоименитым людем российским, о нихже ниже самый ангельский язык к похвалению доволен95 будет."},
  {"id": "ru-mol-0255", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Толгской»"},
  {"id": "ru-mol-0256", "section": "service", "who": "rubric", "text": "(21 августа)"},
  {"id": "ru-mol-0257", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже, Дево Богородице, вышшая Херувимов и Серафимов и святейшая всех святых! Ты, Всеблагая, на Толге икону Твою многоцелебную блаженному святителю Трифону огневидно явити благоволила еси, и ею многая и неизреченная чудеса соделала еси, и ныне содеваеши, по Твоему неизреченному к нам милосердию."},
  {"id": "ru-mol-0258", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Трех Радостей»"},
  {"id": "ru-mol-0259", "section": "service", "who": "rubric", "text": "(8 января)"},
  {"id": "ru-mol-0260", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, всеблагаго Сына Мати всеблагая, царствующаго града и святаго храма сего покровительнице, всем сущим во гресех, скорбех, бедах и болезнех верная предстательнице и заступнице!"},
  {"id": "ru-mol-0261", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Троеручица»"},
  {"id": "ru-mol-0262", "section": "service", "who": "rubric", "text": "(11 июля и 25 июля)"},
  {"id": "ru-mol-0263", "section": "service", "who": "rubric", "text": "О Пресвятая и Преблагословенная Дево, Богородице Марие! Припадаем и покланяемся Тебе пред святою иконою Твоею, воспоминающе преславное чудо Твое, исцелением усеченныя десницы преподобнаго Иоанна Дамаскина от иконы сея явленное, егоже знамение доныне видимо есть на ней, во образе третия руки, ко изображению Твоему приложенныя."},
  {"id": "ru-mol-0264", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «У источника» Пюхтицкой»"},
  {"id": "ru-mol-0265", "section": "service", "who": "rubric", "text": "(1 июля)"},
  {"id": "ru-mol-0266", "section": "service", "who": "rubric", "text": "О Пресвятая и Преблагословенная Мати Сладчайшаго Господа нашего Иисуса Христа! Припадаем и покланяемся Тебе пред светозарным образом Твоим и смиренно молим: прости, Всемилостивая, вся заблуждения наша и вся оскорбления, в ведении или в неведении Сыну Твоему и Спасителю нашему от юности обильно нанесенная неисполнением заповедей Его святых, небрежением к святыне, нерадением в молитве и нетерпением в несении креста нашего."},
  {"id": "ru-mol-0267", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Умиление» (Серафимо-Дивеевской)"},
  {"id": "ru-mol-0268", "section": "service", "who": "rubric", "text": "(10 августа)"},
  {"id": "ru-mol-0269", "section": "service", "who": "rubric", "text": "О Владычице Богородице, души моея услаждение, изсохшаго сердца моего струе Боготочная, потемненнаго ума моего пресветлый светильниче, ленивыя воли моея Путеводительнице, немощи моея сило, наготы облечение, нищеты богатство, неисцелимых ран мощное и скорое врачевание, слез осушение, рыданий утоление, бед претворение, болезней облегчение, уз разрешение, спасения надеждо!"},
  {"id": "ru-mol-0270", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Умиление» (Псково-Печерской)"},
  {"id": "ru-mol-0271", "section": "service", "who": "rubric", "text": "(20 октября, Неделя 7-я по Пасхе, 3 июня, 6 июля, 8 сентября)"},
  {"id": "ru-mol-0272", "section": "service", "who": "rubric", "text": "О Преблагословенная Дево Богородице Владычице! Мати всех страждущих и болезнующих сердцем! Страны нашея и града Защитнице!"},
  {"id": "ru-mol-0273", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Умягчение злых сердец»"},
  {"id": "ru-mol-0274", "section": "service", "who": "rubric", "text": "(в Неделю Всех святых)"},
  {"id": "ru-mol-0275", "section": "service", "who": "rubric", "text": "О многострадальная Мати Божия, превысшая всех дщерей земли по чистоте Твоей и по множеству страданий, Тобою на земли перенесенных! Приими многоболезненная воздыхания наша и сохрани нас под кровом Твоея милости."},
  {"id": "ru-mol-0276", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Успение» Киево-Печерская»"},
  {"id": "ru-mol-0277", "section": "service", "who": "rubric", "text": "(16 мая, 28 августа)"},
  {"id": "ru-mol-0278", "section": "service", "who": "rubric", "text": "О Пресвятая и Пренепорочная Дево Богородице, наша Печерския похвало и украшение, покрове и заступление, истинная Владычице избраннаго удела Твоего; приими нас, недостойных рабов Твоих, убогое моление с верою и любовию приносящих пред чудным образом Твоим."},
  {"id": "ru-mol-0279", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Утоли моя печали»"},
  {"id": "ru-mol-0280", "section": "service", "who": "rubric", "text": "(7 февраля)"},
  {"id": "ru-mol-0281", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Феодоровской»"},
  {"id": "ru-mol-0282", "section": "service", "who": "rubric", "text": "(27 марта и 29 августа)"},
  {"id": "ru-mol-0283", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице Богородице и Приснодево Марие, единая надеждо нам грешным! К Тебе прибегаем и Тебе молим, яко велие имаши дерзновение к рождшемуся от Тебе по плоти Господу Богу и Спасителю нашему Иисусу Христу."},
  {"id": "ru-mol-0284", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Цареградской»"},
  {"id": "ru-mol-0285", "section": "service", "who": "rubric", "text": "(8 мая, 30 сентября)"},
  {"id": "ru-mol-0286", "section": "service", "who": "rubric", "text": "К Тебе, Пресвятей Госпоже Богородице, недостойнии раби Твои прибегаем: Ты бо, Преблагая, едина незлобивая и велемощная к Сыну Твоему, Христу Богу нашему, за ны, грешныя, Ходатаица и Непостыдная Предстательница."},
  {"id": "ru-mol-0287", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Целительница»"},
  {"id": "ru-mol-0288", "section": "service", "who": "rubric", "text": "(1 октября)"},
  {"id": "ru-mol-0289", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Ченстоховской»"},
  {"id": "ru-mol-0290", "section": "service", "who": "rubric", "text": "(19 марта)"},
  {"id": "ru-mol-0291", "section": "service", "who": "rubric", "text": "О Всемилостивая Госпоже, Царице Богородице, от всех родов избранная и всеми роды небесными и земными ублажаемая! Воззри милостивно на предстоящия пред святою иконою Твоею люди сия, усердно молящиеся Тебе и сотвори предстательством Твоим и заступлением у Сына Твоего и Бога нашего, да никтоже отыдет от места сего упования своего тощ и посрамлен в надежде своей; но да приимет кийждо от Тебе вся по благому изволению сердца своего, по нужди и потребе своей, во спасение души и во здравие телу."},
  {"id": "ru-mol-0292", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Черниговской-Гефсиманской»"},
  {"id": "ru-mol-0293", "section": "service", "who": "rubric", "text": "(14 сентября)"},
  {"id": "ru-mol-0294", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Мати Христа Бога нашего, Царице Небеси и земли! Вонми многоболезненному воздыханию душ наших, призри с высоты святыя Твоея на нас, с верою и любовию покланяющихся пречистому образу Твоему: се бо, грехми погружаеми и скорбми обуреваеми, взирающе на Твой образ, яко живущей Ти с нами, приносим смиренная моления наша, не имамы бо иныя помощи, ни инаго предстательства и утешения, токмо Тебе, о, Мати всех скорбящих и обремененных."},
  {"id": "ru-mol-0295", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Черниговской-Ильинской»"},
  {"id": "ru-mol-0296", "section": "service", "who": "rubric", "text": "(29 апреля)"},
  {"id": "ru-mol-0297", "section": "service", "who": "rubric", "text": "Пресвятая Богородице, спаси нас!"},
  {"id": "ru-mol-0298", "section": "service", "who": "rubric", "text": "^ Молитва пред иконою Божией Матери «Экономисса»"},
  {"id": "ru-mol-0299", "section": "service", "who": "rubric", "text": "(18 июля)"},
  {"id": "ru-mol-0300", "section": "service", "who": "rubric", "text": "О Пречистая Владычице Богородице, Всечестнейшая наша Мати Игумение всех православных святых обителей иноческаго жития, во Святей Горе Афонстей и по всей вселенней сущих!"},
  {"id": "ru-mol-0301", "section": "service", "who": "rubric", "text": "Примечания:"},
];

